const BY_SLUG: Map<string, CompanyRecord> = new Map(COMPANIES.map((c) => [c.slug, c]));
const BY_NAME: Map<string, CompanyRecord> = new Map(COMPANIES.map((c) => [c.name.toLowerCase(), c]));

export function getCompanyRecords(): CompanyRecord[] {
  return COMPANIES;
}

export function getCompanyRecord(slug: string): CompanyRecord | null {
  return BY_SLUG.get(slug) ?? null;
}

/** Case-insensitive exact-name lookup (e.g. matching a plain-text company name to its catalog record). */
export function getCompanyRecordByName(name: string): CompanyRecord | null {
  return BY_NAME.get(name.trim().toLowerCase()) ?? null;
}

export const COMPANY_CATEGORIES: string[] = Array.from(
  new Set(COMPANIES.map((c) => c.category)),
);

export const COMPANY_COUNT = COMPANIES.length;

/** Lightweight card projection for the home grid. */
export function toCardData(c: CompanyRecord, roleCount: number): CompanyCardData {
  return {
    slug: c.slug,
    name: c.name,
    category: c.category,
    industry: c.industry,
    hq: c.hq,
    tagline: c.tagline,
    brand: c.brand,
    difficulty: c.difficulty,
    roleCount,
    domain: getCompanyDomain(c.slug) ?? "",
  };
}
